package de.igslandstuhl.database.attendance;import static org.junit.jupiter.api.Assertions.*;import de.igslandstuhl.database.api.*;import com.google.gson.*;import java.io.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;
class AttendanceSecurityTest{@Test void teachersAreStaffButNeverAcceptedAsStudentIdentity(){Teacher teacher=new Teacher(12,"T","Eacher","teacher@example.test","hash");assertTrue(AttendanceRequests.staff(teacher));assertNull(AttendanceRequests.strictStudent(teacher));assertNull(AttendanceRequests.strictStudent(User.ANONYMOUS));}@Test void routeAccessLevelsMatchTheirApplicationLevelChecks()throws Exception{try(InputStream in=getClass().getResourceAsStream("/meta/paths/post_paths.json")){assertNotNull(in);JsonObject root=JsonParser.parseString(new String(in.readAllBytes(),StandardCharsets.UTF_8)).getAsJsonObject();assertEquals("teacher",root.getAsJsonObject("/attendance-manual-arrival").get("access_level").getAsString());assertEquals("public",root.getAsJsonObject("/attendance-checkin").get("access_level").getAsString());assertEquals("public",root.getAsJsonObject("/attendance-pending").get("access_level").getAsString());assertEquals("public",root.getAsJsonObject("/attendance-resume").get("access_level").getAsString());assertEquals("public",root.getAsJsonObject("/attendance-signage-token").get("access_level").getAsString());assertEquals("public",root.getAsJsonObject("/attendance-display-token").get("access_level").getAsString());}String requests=new String(java.nio.file.Files.readAllBytes(java.nio.file.Path.of("src/main/java/de/igslandstuhl/database/attendance/AttendanceRequests.java")),StandardCharsets.UTF_8);assertTrue(requests.contains("Student s=strictStudent(r.getUser())"));assertTrue(requests.contains("PENDING.consume"));}@Test void legacyDisplayClientCannotSupplyAnArbitraryBaseUrl()throws Exception{String source=new String(getClass().getResourceAsStream("/js/site/attendance-display.js").readAllBytes(),StandardCharsets.UTF_8);assertTrue(source.contains("attendance-display-token"));String requests=new String(java.nio.file.Files.readAllBytes(java.nio.file.Path.of("src/main/java/de/igslandstuhl/database/attendance/AttendanceRequests.java")),StandardCharsets.UTF_8);assertFalse(requests.contains("validBaseUrl"));assertFalse(requests.contains("r.getString(\"baseUrl\")"));assertTrue(requests.contains("if(!signage.authenticated(r.getCookies()))"));}}
